#[test]
fn test_dot_is_a_child_of_its_list() {
    // the dot belongs to the inner list, not the outer one
    let o = outline("((a . b) c)");
    assert_eq!(o.iter().filter(|n| n.0 == "dot").count(), 1);
    assert_eq!(o[1], ("list", 0, 11));
    assert_eq!(o[2], ("list", 1, 8));
}

