#[test]
fn test_spans_list_and_quote() {
    // "  (a 'b)"  -> '(' at 2, 'a' at 3, quote at 5, 'b' at 6, ')' at 7
    assert_eq!(
        outline("  (a 'b)"),
        [
            ("root", 0, 8),
            ("list", 2, 8),
            ("sym", 3, 4),
            ("quote", 5, 7),
            ("sym", 6, 7),
        ]
    );
}

#[test]
fn test_spans_dotted_list() {
    assert_eq!(
        outline("(a . b)"),
        [
            ("root", 0, 7),
            ("list", 0, 7),
            ("sym", 1, 2),
            ("dot", 3, 4),
            ("sym", 5, 6),
        ]
    );
}

#[test]
fn test_spans_literals() {
    assert_eq!(
        outline("(12 3.5 \"s\")"),
        [
            ("root", 0, 12),
            ("list", 0, 12),
            ("int", 1, 3),
            ("real", 4, 7),
            ("str", 8, 11),
        ]
    );
}

#[test]
fn test_spans_are_in_bytes_not_chars() {
    // 'é' is two bytes: string is bytes 1..5, x is at 6
    assert_eq!(
        outline("(\"é\" x)"),
        [("root", 0, 8), ("list", 0, 8), ("str", 1, 5), ("sym", 6, 7)]
    );
}

#[test]
fn test_root_span_covers_trailing_trivia() {
    assert_eq!(outline("a  "), [("root", 0, 3), ("sym", 0, 1)]);
}

#[test]
fn test_spans_are_well_nested_on_realistic_source() {
    assert_well_nested(";; header\n(defun c:foo (/ a)\n  (setq a '(1 . 2)) ; t\n  (princ))\n");
}

#[test]
fn test_spans_are_well_nested_on_broken_source() {
    assert_well_nested("(a (b (c\n(defun f ()))) \"x");
}

