#[test]
fn test_stray_close_alone() {
    check(")", "<>", &[(UnmatchedCloseParen, 0, 1)]);
}

#[test]
fn test_stray_close_between_forms() {
    check("a ) b", "<a b>", &[(UnmatchedCloseParen, 2, 3)]);
}

#[test]
fn test_stray_close_after_balanced_list() {
    check("(a))", "<(a)>", &[(UnmatchedCloseParen, 3, 4)]);
}

#[test]
fn test_stray_close_after_defun_recovery() {
    check(
        "(a\n(defun f ()))",
        "<(a) (defun f ())>",
        &[(UnclosedList, 2, 2), (UnmatchedCloseParen, 15, 16)],
    );
}

