#[test]
fn test_unterminated_string_is_a_string_node_plus_error() {
    check("\"abc", "<\"abc>", &[(UnterminatedString, 0, 4)]);
    assert_eq!(outline("\"abc")[1], ("str", 0, 4));
}

#[test]
fn test_unterminated_string_inside_list_also_leaves_list_unclosed() {
    check(
        "(a \"b",
        "<(a \"b)>",
        &[(UnterminatedString, 3, 5), (UnclosedList, 5, 5)],
    );
}

#[test]
fn test_unterminated_block_comment_alone() {
    check(";| oops", "<>", &[(UnterminatedBlockComment, 0, 7)]);
}

#[test]
fn test_unterminated_block_comment_inside_list() {
    // ASSUMPTION: the broken comment counts as trivia when placing the
    // unclosed-list error, so it lands after `a`, not after the comment.
    check(
        "(a ;| oops",
        "<(a)>",
        &[(UnclosedList, 2, 2), (UnterminatedBlockComment, 3, 10)],
    );
}

