#[test]
fn test_leading_dot_is_misplaced() {
    check("(. 1)", "<(. 1)>", &[(MisplacedDot, 1, 2)]);
}

#[test]
fn test_trailing_dot_is_misplaced() {
    check("(1 .)", "<(1 .)>", &[(MisplacedDot, 3, 4)]);
}

#[test]
fn test_lone_dot_in_list_is_misplaced() {
    check("(.)", "<(.)>", &[(MisplacedDot, 1, 2)]);
}

#[test]
fn test_extra_cdrs_after_dot() {
    // the error covers the extra element
    check("(1 . 2 3)", "<(1 . 2 3)>", &[(ExtraCdrsInDottedPair, 7, 8)]);
}

#[test]
fn test_several_extra_cdrs_are_one_error() {
    // extras are `3 4`: one error from the start of 3 to the end of 4
    check(
        "(1 . 2 3 4)",
        "<(1 . 2 3 4)>",
        &[(ExtraCdrsInDottedPair, 7, 10)],
    );
}

#[test]
fn test_second_dot_counts_as_extra_cdrs() {
    // extras are `. 3`; the second dot gets no MisplacedDot of its own
    check(
        "(1 . 2 . 3)",
        "<(1 . 2 . 3)>",
        &[(ExtraCdrsInDottedPair, 7, 10)],
    );
}

#[test]
fn test_dotted_error_does_not_disturb_the_rest() {
    check("(a (. b) c)", "<(a (. b) c)>", &[(MisplacedDot, 4, 5)]);
}

#[test]
fn test_lone_dot_at_top_level_is_misplaced() {
    check(".", "<.>", &[(MisplacedDot, 0, 1)]);
}

#[test]
fn test_dot_between_top_level_forms_is_misplaced() {
    check("1 . 2", "<1 . 2>", &[(MisplacedDot, 2, 3)]);
}

#[test]
fn test_lone_quote_at_eof() {
    // zero-width error right after the quote; Missing child so Quote is total
    check("'", "<'?>", &[(QuoteMissingOperand, 1, 1)]);
    assert_eq!(
        outline("'"),
        [("root", 0, 1), ("quote", 0, 1), ("missing", 1, 1)]
    );
}

#[test]
fn test_lone_quote_before_close_paren() {
    // the `)` still closes the enclosing list
    check("(' )", "<('?)>", &[(QuoteMissingOperand, 2, 2)]);
}

#[test]
fn test_quote_of_quote_missing_operand() {
    check("''", "<''?>", &[(QuoteMissingOperand, 2, 2)]);
}

